def natural_last_modified(self):
    if self.last_modified is None:
        return "?"
    else:
        last_modified = parsedate_to_datetime(self.last_modified)
        now = datetime.now(timezone.utc)
        tense = "from now" if last_modified > now else "ago"
        return "{0} {1}".format(humanize.naturaldelta(now - last_modified), tense)

def style_source_with_status(source, status, porcelain=False):
    if porcelain:
        return "{nick}\t{url}\t{status}\t{content_length}\t{last_modified}".format(
            nick=source.nick,
            url=source.url,
            status=status.status_code,
            content_length=status.content_length,
            last_modified=status.last_modified)
    else:
        if hasattr(status, "status_code") and status.status_code == 200:
            scolor, smessage = "green", str(status.status_code)
        elif status:
            scolor, smessage = "red", str(status.status_code)
        else:
            scolor, smessage = "red", "ERROR"
        return "➤ {nick} @ {url} [{content_length}, {last_modified}] ({status})".format(
            nick=click.style(source.nick, bold=True, fg=scolor),
            url=source.url,
            status=click.style(smessage, fg=scolor),
            content_length=status.natural_content_length,
            last_modified=status.natural_last_modified)

def last_modified(self, url):
    """Returns saved 'Last-Modified' header, if available."""
    try:
        return self.cache[url]["last_modified"]
    except KeyError:
        return None

async def retrieve_file(client, source, limit, cache):
    is_cached = cache.is_cached(source.url) if cache else None
    headers = {"If-Modified-Since": cache.last_modified(source.url)} if is_cached else {}

    try:
        response = await client.get(source.url, headers=headers)
        content = await response.text()
    except Exception as e:
        if is_cached:
            logger.debug("{0}: {1} - using cached content".format(source.url, e))
            return cache.get_tweets(source.url, limit)
        else:
            logger.debug("{0}: {1}".format(source.url, e))
            return []

    if response.status == 200:
        tweets = parse_tweets(content.splitlines(), source)

        if cache:
            last_modified_header = response.headers.get("Last-Modified")
            if last_modified_header:
                logger.debug("{0} returned 200 and Last-Modified header - adding content to cache".format(source.url))
                cache.add_tweets(source.url, last_modified_header, tweets)
            else:
                logger.debug("{0} returned 200 but no Last-Modified header - can’t cache content".format(source.url))
        else:
            logger.debug("{0} returned 200".format(source.url))

        return sorted(tweets, reverse=True)[:limit]

    elif response.status == 410 and is_cached:
        # 410 Gone:
        # The resource requested is no longer available,
        # and will not be available again.
        logger.debug("{0} returned 410 - deleting cached content".format(source.url))
        cache.remove_tweets(source.url)
        return []

    elif is_cached:
        logger.debug("{0} returned {1} - using cached content".format(source.url, response.status))
        return cache.get_tweets(source.url, limit)

    else:
        logger.debug("{0} returned {1}".format(source.url, response.status))
        return []

def last_updated(self):
    """Returns *NIX timestamp of last update of the cache."""
    try:
        return self.cache["last_update"]
    except KeyError:
        return 0

def is_valid(self):
    """Checks if the cache is considered to be up-to-date."""
    if timestamp() - self.last_updated <= self.update_interval:
        return True
    else:
        return False

def mark_updated(self):
    """Mark cache as updated at current *NIX timestamp"""
    if not self.is_valid:
        self.cache["last_update"] = timestamp()

def is_cached(self, url):
    """Checks if specified URL is cached."""
    try:
        return True if url in self.cache else False
    except TypeError:
        return False

def add_tweets(self, url, last_modified, tweets):
    """Adds new tweets to the cache."""
    try:
        self.cache[url] = {"last_modified": last_modified, "tweets": tweets}
        self.mark_updated()
        return True
    except TypeError:
        return False

def get_tweets(self, url, limit=None):
    """Retrieves tweets from the cache."""
    try:
        tweets = self.cache[url]["tweets"]
        self.mark_updated()
        return sorted(tweets, reverse=True)[:limit]
    except KeyError:
        return []

def remove_tweets(self, url):
    """Tries to remove cached tweets."""
    try:
        del self.cache[url]
        self.mark_updated()
        return True
    except KeyError:
        return False

def get_remote_tweets(sources, limit=None, timeout=5.0, cache=None):
    async def start_loop():
        conn = aiohttp.TCPConnector(use_dns_cache=True)
        headers = generate_user_agent()

        async with aiohttp.ClientSession(connector=conn, headers=headers, conn_timeout=timeout) as client:
            return await process_sources_for_file(client, sources, limit, cache)

    return asyncio.run(start_loop())

def get_remote_status(sources, timeout=5.0):
